// Writes the Stripe publishable key for the reference app from STRIPE_PUBLISHABLE_KEY.
// The generated file is git-ignored, so no key is stored in the repository.
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const PLACEHOLDER = 'pk_test_REPLACE_ME';
const target = join(
  dirname(fileURLToPath(import.meta.url)),
  '../src/app/spartacus/features/stripe/stripe-keys.generated.ts'
);

const key = process.env.STRIPE_PUBLISHABLE_KEY || PLACEHOLDER;
if (key === PLACEHOLDER) {
  console.warn(
    '[stripe] STRIPE_PUBLISHABLE_KEY is not set. Using a placeholder; Stripe Elements will not load.'
  );
}

writeFileSync(
  target,
  `// Generated by scripts/write-stripe-config.mjs. Do not edit or commit.\nexport const STRIPE_PUBLISHABLE_KEY = ${JSON.stringify(key)};\n`
);
